-- Customer capture regression using the maintained 0264 loop fixture and engine.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
set local test.fms.customer_integration='true';
\ir helpers/fms_visit_assignment_fixture.psql
select save_form_customer_mapping((select id from visit_assignment_fixture where name='form'),'{"schemaVersion":1,"enabled":true,"channel":"INSTAGRAM","identityScope":"synthetic-loop","fields":[{"fieldKey":"client_name","mode":"both","destination":"primary_name"},{"fieldKey":"budget","mode":"both","destination":"budget"}]}');
insert into visit_assignment_fixture select 'loop_flow',create_fms_revision_with_audit((select id from visit_assignment_fixture where name='flow'));
reset role;
insert into visit_assignment_fixture select 'loop_'||stage_key,id from fms_stages where fms_flow_id=(select id from visit_assignment_fixture where name='loop_flow');
update fms_stages set planned_time_rule=jsonb_set(planned_time_rule,'{assignment,sources}',(planned_time_rule#>'{assignment,sources}')||jsonb_build_array(jsonb_build_object('sourceStageKey','demo','formTemplateId',form_template_id,'fieldKey','next_employee'))) where id=(select id from visit_assignment_fixture where name='loop_call');
update fms_stages set planned_time_rule=planned_time_rule||'{"decisionMode":"decision","decisionOptions":[{"key":"repeat","label":"Follow up again"},{"key":"exit","label":"Continue"}]}'::jsonb,default_next_stage_id=(select id from visit_assignment_fixture where name='loop_call') where id=(select id from visit_assignment_fixture where name='loop_demo');
insert into fms_branch_rules(fms_stage_id,source_type,condition_field,condition_operator,condition_value,next_stage_id,sort_order) values((select id from visit_assignment_fixture where name='loop_demo'),'outcome','outcome','equals','exit',(select id from visit_assignment_fixture where name='loop_negotiation'),0);
set local role authenticated;
select lives_ok($$select publish_fms_flow_with_audit((select id from visit_assignment_fixture where name='loop_flow'))$$,'human follow-up loop with an exit publishes');
insert into visit_assignment_fixture select 'loop_instance',(submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('client_name','Synthetic loop customer','budget',100,'next_employee',(select id from visit_assignment_fixture where name='b')),'fms_entry',(select id from fms_starter_assignments where fms_flow_id=(select id from visit_assignment_fixture where name='loop_flow') and user_profile_id=(select id from visit_assignment_fixture where name='a')),gen_random_uuid())->>'instance_id')::uuid;
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('client_name','Synthetic loop customer','budget',100,'next_employee',(select id from visit_assignment_fixture where name='c')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call')),gen_random_uuid());
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='c_auth'),true);
select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('client_name','Synthetic loop customer','budget',100,'next_employee',(select id from visit_assignment_fixture where name='d')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_demo')),gen_random_uuid(),p_outcome=>'repeat');
reset role;
select is((select count(*)::integer from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call')),2,'return route creates a fresh visit');
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call') and visit_number=2),array[(select id from visit_assignment_fixture where name='d')],'repeat visit takes its employee from the latest causal form');
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call') and visit_number=1),array[(select id from visit_assignment_fixture where name='b')],'earlier visit assignment remains immutable');
select ok((select form_submission_id is not null and status='completed' from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call') and visit_number=1),'earlier completion form remains attached');
select is((select count(*)::integer from fms_stage_assignment_decisions decision join fms_instance_stages visit on visit.id=decision.target_instance_stage_id where visit.fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and visit.fms_stage_id=(select id from visit_assignment_fixture where name='loop_call')),2,'each visit has its own provenance decision');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='d_auth'),true);
set local role authenticated;
select ok(exists(select 1 from jsonb_array_elements(get_fms_assigned_work_context((select id from visit_assignment_fixture where name='loop_instance'),(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call') and visit_number=2))->'journey') entry where (entry->>'id')::uuid=(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call') and visit_number=1)),'received work journey retains the prior actual loop visit');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='d_auth'),true);
set local role authenticated;
select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('client_name','Synthetic loop customer','budget',200,'next_employee',(select id from visit_assignment_fixture where name='e')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call') and visit_number=2),gen_random_uuid());
reset role;
set constraints all immediate;
select is((select count(*)::integer from crm_sync.customer_events where source_type='form.submitted' and payload#>>'{workflow,instanceId}'=(select id::text from visit_assignment_fixture where name='loop_instance') and payload#>>'{workflow,stageId}'=(select id::text from visit_assignment_fixture where name='loop_call')),2,'repeated customer stage retains two original submission events');
select is((select count(distinct payload#>>'{workflow,instanceStageId}')::integer from crm_sync.customer_events where source_type='form.submitted' and payload#>>'{workflow,instanceId}'=(select id::text from visit_assignment_fixture where name='loop_instance') and payload#>>'{workflow,stageId}'=(select id::text from visit_assignment_fixture where name='loop_call')),2,'customer evidence identifies visits by durable instance-stage ID');
select ok(exists(select 1 from crm_sync.customer_events e cross join lateral jsonb_array_elements(e.payload->'answers') a where e.payload#>>'{workflow,instanceId}'=(select id::text from visit_assignment_fixture where name='loop_instance') and a->>'fieldKey'='budget' and a->'original'='200'::jsonb),'latest loop answer coexists with original prior answers');
select * from finish();
rollback;
